//! Differential test against the C++ oracle
//! `tools/oracle/hyperedge_oracle.cpp` (golden output in
//! `tests/golden/hyperedge_oracle.txt`, regenerated by
//! `tools/oracle/build_hyperedge_oracle.sh`).
//!
//! The golden file holds, per scene, the scene DSL (see the oracle source
//! for the command reference) and the oracle's output.  This test replays
//! every scene through the Rust port and must reproduce the output byte for
//! byte:
//!  (a) `mtst-*`: MinimumTerminalSpanningTree trees (constructInterleaved /
//!      constructSequential), vertex sptfDist / pathNext, hyperedge-segment
//!      edge flags;
//!  (b) `reroute-*`: HyperedgeRerouter::performRerouting() results (routes,
//!      connector ends, junctions, new/deleted object lists);
//!  (c) `improve-astar-*` / `improve-hand-*`: HyperedgeImprover::execute()
//!      results on A* routes and on hand-made display routes.
//! `full-*` scenes run the real processTransaction() including orthogonal
//! nudging; they are checked by an #[ignore]d test until
//! `improve_orthogonal_routes` is ported.
//!
//! Set `ORACLE_SCENE=name` to run a single scene and `ORACLE_PRINT=1` to
//! print the Rust output.

#![allow(clippy::uninlined_format_args)]

#[path = "hyperedge_dsl/mod.rs"]
mod hyperedge_dsl;

use std::collections::BTreeMap;

use hyperedge_dsl::{parse_golden, run_scene};

fn check_scenes(full_pipeline: bool) {
    let path = std::env::var("ORACLE_GOLDEN")
        .unwrap_or_else(|_| concat!(env!("CARGO_MANIFEST_DIR"), "/tests/golden/hyperedge_oracle.txt").to_string());
    let text = std::fs::read_to_string(&path).expect("golden file");
    let scenes = parse_golden(&text);
    assert!(std::env::var("ORACLE_GOLDEN").is_ok() || scenes.len() > 100, "golden file looks truncated");
    let only = std::env::var("ORACLE_SCENE").ok();
    let print = std::env::var("ORACLE_PRINT").is_ok();
    let mut failures = Vec::new();
    let mut counts: BTreeMap<String, (usize, usize)> = BTreeMap::new();
    for scene in scenes.iter() {
        if scene.name.starts_with("full-") != full_pipeline {
            continue;
        }
        if let Some(o) = only.as_ref() {
            if &scene.name != o {
                continue;
            }
        }
        let kind = scene.name.trim_end_matches(|c: char| c.is_ascii_digit()).to_string();
        let result = std::panic::catch_unwind(|| run_scene(&scene.dsl));
        let entry = counts.entry(kind).or_insert((0, 0));
        entry.0 += 1;
        match result {
            Err(e) => {
                let msg = e
                    .downcast_ref::<String>()
                    .cloned()
                    .or_else(|| e.downcast_ref::<&str>().map(|s| s.to_string()))
                    .unwrap_or_default();
                failures.push(format!("{}: panicked: {}", scene.name, msg));
            }
            Ok(out) => {
                if print {
                    println!("#scene {}", scene.name);
                    for l in out.iter() {
                        println!("{}", l);
                    }
                }
                if out != scene.out {
                    let first = out
                        .iter()
                        .zip(scene.out.iter())
                        .position(|(a, b)| a != b)
                        .unwrap_or(out.len().min(scene.out.len()));
                    failures.push(format!(
                        "{}: first difference at output line {}:\n  rust:   {}\n  oracle: {}",
                        scene.name,
                        first,
                        out.get(first).map(|s| s.as_str()).unwrap_or("<none>"),
                        scene.out.get(first).map(|s| s.as_str()).unwrap_or("<none>")
                    ));
                } else {
                    entry.1 += 1;
                }
            }
        }
    }
    for (k, (n, ok)) in counts.iter() {
        println!("{}: {}/{} scenes match", k, ok, n);
    }
    assert!(failures.is_empty(), "{} scene(s) differ:\n{}", failures.len(), failures.join("\n"));
}

#[test]
fn hyperedge_stages_match_cpp_oracle() {
    check_scenes(false);
}

#[test]
#[ignore = "needs improve_orthogonal_routes"]
fn hyperedge_full_pipeline_matches_cpp_oracle() {
    check_scenes(true);
}
